type CourseCategory = keyof typeof courses

interface Course {
  title: string
  duration: string
  image: string
  category?: string
}

export function CoursesSection() {
  const [activeTab, setActiveTab] = useState<string>("all")
  const [isVisible, setIsVisible] = useState(false)
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null)
  const [isModalOpen, setIsModalOpen] = useState(false)
  const sectionRef = useRef<HTMLElement>(null)

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true)
        }
      },
      { threshold: 0.1 },
    )

    if (sectionRef.current) {
      observer.observe(sectionRef.current)
    }

    return () => observer.disconnect()
  }, [])

  const getDisplayedCourses = (): Course[] => {
    if (activeTab === "all") {
      return Object.values(courses).flat()
    }
    return courses[activeTab as CourseCategory] || []
  }

  const handleCourseClick = (course: Course) => {
    setSelectedCourse(course)
    setIsModalOpen(true)
  }

  const closeModal = () => {
    setIsModalOpen(false)
    setSelectedCourse(null)
  }

  return (
    <>
      <section id="courses" ref={sectionRef} className="py-24 md:py-32 px-6 md:px-12 lg:px-16 bg-cream">
        <div className="container mx-auto">
          <div className={`text-center mb-16 ${isVisible ? "animate-slide-up" : "opacity-0"}`}>
            <div className="inline-flex items-center gap-2 bg-green/20 text-navy px-4 py-2 rounded-full mb-6">
              <Sparkles className="w-4 h-4" />
              <span className="text-sm font-medium">Explore Our Programs</span>
            </div>
            <h2 className="font-serif text-4xl md:text-5xl lg:text-6xl font-bold text-navy">
              Explore Our All Type Of Courses<span className="text-blue">.</span>
            </h2>
          </div>

          <div
            className={`flex flex-wrap justify-center gap-3 md:gap-4 mb-16 ${
              isVisible ? "animate-fade-in animation-delay-200" : "opacity-0"
            }`}
          >
            {tabs.map((tab, index) => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`px-5 py-2.5 rounded-full transition-all duration-300 font-medium text-sm md:text-base transform hover:scale-105 ${
                  activeTab === tab.id
                    ? "bg-navy text-white shadow-lg shadow-navy/20"
                    : "text-navy/70 hover:text-navy bg-white hover:bg-green/10 border border-navy/10"
                }`}
                style={{ animationDelay: `${index * 0.05}s` }}
              >
                {tab.name}
              </button>
            ))}
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 md:gap-8">
            {getDisplayedCourses().map((course, index) => (
              <div
                key={`${course.title}-${index}`}
                onClick={() => handleCourseClick(course)}
                className={`group relative rounded-3xl overflow-hidden bg-card shadow-sm hover:shadow-2xl transition-all duration-500 hover:-translate-y-4 cursor-pointer ${
                  isVisible ? "animate-scale-in" : "opacity-0"
                }`}
                style={{ animationDelay: `${(index % 8) * 0.08}s` }}
              >
                <div className="relative h-60 overflow-hidden">
                  <Image
                    src={course.image || "/placeholder.svg"}
                    alt={course.title}
                    fill
                    className="object-cover transition-transform duration-700 group-hover:scale-110"
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-navy/70 via-navy/20 to-blue/5 opacity-0 group-hover:opacity-100 transition-opacity duration-500" />

                  <div className="absolute top-4 right-4 bg-white rounded-full p-2.5 opacity-0 group-hover:opacity-100 transition-all duration-300 group-hover:scale-110 shadow-lg group-hover:rotate-12">
                    <ArrowUpRight className="w-5 h-5 text-navy" />
                  </div>

                  <div className="absolute top-4 left-4 bg-green/90 text-navy px-3 py-1 rounded-full text-xs font-semibold opacity-0 group-hover:opacity-100 transition-all duration-300 transform -translate-y-2 group-hover:translate-y-0">
                    {course.category}
                  </div>
                </div>

                <div className="p-5 bg-card group-hover:bg-green/5 transition-colors duration-300">
                  <h3 className="font-semibold text-navy mb-2 line-clamp-2 group-hover:text-blue transition-colors text-lg">
                    {course.title}
                  </h3>
                  <div className="flex items-center justify-between">
                    <p className="text-muted-foreground text-sm">{course.duration}</p>
                    <span className="text-xs text-navy/50 group-hover:text-green font-medium transition-colors">
                      View Details
                    </span>
                  </div>
                </div>

                <div className="absolute bottom-0 left-0 right-0 h-1 bg-gradient-to-r from-blue via-green to-blue transform scale-x-0 group-hover:scale-x-100 transition-transform duration-500 origin-left" />
              </div>
            ))}
          </div>
        </div>
      </section>

      <CourseModal course={selectedCourse} isOpen={isModalOpen} onClose={closeModal} />
    </>
  )
}
